tape( 'the function treats NaN as falsy (row-major)', function test( t ) {
	var data;
	var out;

	data = [ NaN, 1.0, 1.0, 1.0 ];
	out = gindexOfTruthyRow( 2, 2, data, 2, 1, 0 );
	t.strictEqual( out, 1, 'returns expected value' );
	t.end();
});

tape( 'the function treats NaN as falsy (column-major)', function test( t ) {
	var data;
	var out;

	data = [ 1.0, 1.0, 1.0, NaN ];
	out = gindexOfTruthyRow( 2, 2, data, 1, 2, 0 );
	t.strictEqual( out, 0, 'returns expected value' );
	t.end();
});

tape( 'the function treats NaN as falsy (accessors)', function test( t ) {
	var data;
	var out;

	data = toAccessorArray( [ NaN, 1.0, 1.0, 1.0 ] );
	out = gindexOfTruthyRow( 2, 2, data, 2, 1, 0 );
	t.strictEqual( out, 1, 'returns expected value' );
	t.end();
});
